const { event, haloApiUrl, haloServiceKey, heraldUrl, heraldKey } = input;
const p = event && event.data;
if (!p || !p.orderId) return { sent: 0, reason: 'no-payload' };
if (!haloApiUrl || !haloServiceKey || !heraldUrl || !heraldKey) {
  console.error('[halo-order-email] not configured');
  return { sent: 0, reason: 'not-configured' };
}
const renderRes = await fetch(`${haloApiUrl}/internal/commerce/render-order-emails`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${haloServiceKey}` },
  body: JSON.stringify(p)
});
if (!renderRes.ok) {
  console.error(`[halo-order-email] render failed: ${renderRes.status}`);
  return { sent: 0, reason: 'render-failed' };
}
const { buyer, seller } = await renderRes.json();
const from = `${p.storeName} <orders@send.omni.dev>`;
const targets = [[p.buyerEmail, buyer]];
if (p.sellerEmail && seller) targets.push([p.sellerEmail, seller]);
let sent = 0;
for (const [to, tpl] of targets) {
  if (!to || !tpl) continue;
  const res = await fetch(`${heraldUrl}/messages`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${heraldKey}` },
    body: JSON.stringify({ to, from, subject: tpl.subject, html: tpl.html, idempotencyKey: `halo.order.confirmed:${p.orderId}:${to}` })
  });
  if (!res.ok) { console.error(`[halo-order-email] herald failed for ${to}: ${res.status}`); continue; }
  sent++;
}
return { sent };
